		} else {
			Level().debug_renderer().draw_line(Fidentity,v[0],v[1],c);
			Level().debug_renderer().draw_line(Fidentity,v[1],v[2],c);
			Level().debug_renderer().draw_line(Fidentity,v[2],v[0],c);
		}
	}
};

